#include <iostream>
#define PART1 "This is part one: "
#define PART2 "This is part two"
int main() {
  const char* combined = PART1 ## PART2; // Compile-time concatenation
  std::cout << combined << std::endl;
  //Attempting to concatenate with variables requires runtime methods:
  std::string var1 = "Variable one: ";
  std::string var2 = "Variable two";
  std::string combined_var = var1 + var2; //Runtime concatenation
  std::cout << combined_var << std::endl;
  return 0;
}
